#include <iostream>
#include <string>
#include <vector>

// A trace recorder: the last `cap` values written, oldest first.
//
// This implementation is BROKEN. Find the bug and fix it; the
// specification is in the problem statement, and any implementation
// that meets it is accepted.

int main()
{
    int cap{};
    int m{};
    std::cin >> cap >> m;

    std::vector<int> buf(static_cast<std::size_t>(cap), 0);
    int start{ 0 };   // index of the oldest value held
    int n{ 0 };       // how many values are held

    for (int i = 0; i < m; ++i)
    {
        std::string cmd;
        std::cin >> cmd;

        if (cmd == "write")
        {
            int v{};
            std::cin >> v;
            buf[static_cast<std::size_t>((start + n) % cap)] = v;
            if (n < cap) { ++n; }
        }
        else if (cmd == "count")
        {
            std::cout << n << "\n";
        }
        else if (cmd == "dump")
        {
            if (n == 0)
            {
                std::cout << "empty\n";
                continue;
            }
            for (int k = 0; k < n; ++k)
            {
                std::cout << buf[static_cast<std::size_t>((start + k) % cap)]
                          << (k + 1 == n ? '\n' : ' ');
            }
        }
    }

    return 0;
}
